import React, { useEffect, useRef, useState } from 'react';
import { OBJECT_CATALOG } from './objectCatalog';

const VIEW_WIDTH = 600;
const VIEW_HEIGHT = 400;

function worldToScreen(pos, bounds) {
  const xRange = bounds.x[1] - bounds.x[0] || 1;
  const zRange = bounds.z[1] - bounds.z[0] || 1;
  const sx = ((pos.x - bounds.x[0]) / xRange) * VIEW_WIDTH;
  const sy = VIEW_HEIGHT - ((pos.z - bounds.z[0]) / zRange) * VIEW_HEIGHT;
  return { x: sx, y: sy };
}

export default function CanvasEditorMinimal({ uinJSON, onChange }) {
  const canvasRef = useRef(null);
  const [selectedType, setSelectedType] = useState('human');
  const [position, setPosition] = useState({ x: 0, y: 0, z: 0 });
  const [localError, setLocalError] = useState('');

  let doc = null;
  try {
    doc = JSON.parse(uinJSON || '{}');
  } catch (e) {
    doc = null;
  }

  const bounds = doc?.canvas?.bounds || { x: [-10, 10], y: [-10, 10], z: [-5, 5] };
  const objects = Array.isArray(doc?.objects) ? doc.objects : [];

  // Rendering
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !doc) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, VIEW_WIDTH, VIEW_HEIGHT);

    // Background
    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, VIEW_WIDTH, VIEW_HEIGHT);

    // Grid
    ctx.strokeStyle = '#1f2937';
    ctx.lineWidth = 1;
    for (let i = 1; i < 6; i++) {
      const x = (VIEW_WIDTH / 6) * i;
      const y = (VIEW_HEIGHT / 6) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, VIEW_HEIGHT);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(VIEW_WIDTH, y);
      ctx.stroke();
    }

    // Objects
    objects.forEach((obj) => {
      if (!obj.position) return;
      const { x, y } = worldToScreen(obj.position, bounds);
      const spec = OBJECT_CATALOG.find(entry => entry.type === obj.type) || {};
      const color = spec.color || '#22c55e';
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, 10, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#e5e7eb';
      ctx.font = '10px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText(obj.type || '?', x, y - 14);
    });

    // Preview object at current position
    const { x: px, y: py } = worldToScreen(position, bounds);
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(px, py, 10, 0, Math.PI * 2);
    ctx.stroke();

  }, [uinJSON, position]);

  const handleAddObject = () => {
    if (!doc) return;

    const newDoc = { ...doc, objects: [...objects] };
    const idSuffix = objects.length + 1;

    const newObject = {
      id: `${selectedType}${idSuffix}`,
      type: selectedType,
      position: { ...position }
    };

    newDoc.objects.push(newObject);
    try {
      onChange(JSON.stringify(newDoc, null, 2));
      setLocalError('');
    } catch (e) {
      setLocalError(e.message);
    }
  };

  const disabled = !doc;

  return (
    <div className="bg-gray-800 rounded-lg p-4 flex flex-col h-full">
      <div className="flex items-center justify-between mb-3">
        <h2 className="text-lg font-semibold">Canvas Editor</h2>
      </div>

      {localError && (
        <div className="mb-3 p-2 bg-red-900/30 border border-red-700 rounded text-red-300 text-sm">
          {localError}
        </div>
      )}

      {/* Control Panel */}
      <div className="mb-4 p-3 bg-gray-700 rounded border border-gray-600">
        <div className="grid grid-cols-2 gap-4">
          {/* Object Type */}
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-1">
              Object Type
            </label>
            <select
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
              className="w-full bg-gray-600 text-white px-2 py-1 rounded border border-gray-500 text-sm"
              disabled={disabled}
            >
              {OBJECT_CATALOG.map((entry) => (
                <option key={entry.type} value={entry.type}>
                  {entry.label}
                </option>
              ))}
            </select>
          </div>

          {/* Add Button */}
          <div className="flex items-end">
            <button
              onClick={handleAddObject}
              disabled={disabled}
              className="px-4 py-1 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-600 text-white rounded text-sm font-medium"
            >
              Add Object
            </button>
          </div>
        </div>

        {/* Position Controls */}
        <div className="mt-3">
          <label className="block text-sm font-medium text-gray-300 mb-2">
            Position (X, Y, Z)
          </label>
          <div className="grid grid-cols-3 gap-2">
            <input
              type="number"
              value={position.x}
              onChange={(e) => setPosition(prev => ({ ...prev, x: parseFloat(e.target.value) || 0 }))}
              className="bg-gray-600 text-white px-2 py-1 rounded border border-gray-500 text-sm"
              placeholder="X"
              disabled={disabled}
            />
            <input
              type="number"
              value={position.y}
              onChange={(e) => setPosition(prev => ({ ...prev, y: parseFloat(e.target.value) || 0 }))}
              className="bg-gray-600 text-white px-2 py-1 rounded border border-gray-500 text-sm"
              placeholder="Y"
              disabled={disabled}
            />
            <input
              type="number"
              value={position.z}
              onChange={(e) => setPosition(prev => ({ ...prev, z: parseFloat(e.target.value) || 0 }))}
              className="bg-gray-600 text-white px-2 py-1 rounded border border-gray-500 text-sm"
              placeholder="Z"
              disabled={disabled}
            />
          </div>
        </div>
      </div>

      {/* Canvas */}
      <div className="flex-1 flex items-center justify-center">
        <canvas
          ref={canvasRef}
          width={VIEW_WIDTH}
          height={VIEW_HEIGHT}
          className="border border-gray-600 rounded"
          style={{ imageRendering: 'pixelated' }}
        />
      </div>

      {/* Instructions */}
      <div className="mt-3 text-xs text-gray-400">
        <p>• Select object type and set position</p>
        <p>• Click "Add Object" to place it</p>
        <p>• Blue circle shows preview position</p>
      </div>
    </div>
  );
}
